changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.text_gated_search_allowed_384( p_query nexus.vector(384), p_query_text text, p_chashes bytea[], p_collections text[], p_where jsonb, p_where_path text, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_384 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_384 IS NOT NULL AND c.chash = ANY(p_chashes) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (c.chunk_tsv @@ plainto_tsquery('english', p_query_text) OR p_query_text OPERATOR(nexus.<%) c.chunk_text) ORDER BY c.embedding_384 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.text_gated_search_allowed_768( p_query nexus.vector(768), p_query_text text, p_chashes bytea[], p_collections text[], p_where jsonb, p_where_path text, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_768 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_768 IS NOT NULL AND c.chash = ANY(p_chashes) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (c.chunk_tsv @@ plainto_tsquery('english', p_query_text) OR p_query_text OPERATOR(nexus.<%) c.chunk_text) ORDER BY c.embedding_768 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $$;
CREATE OR REPLACE FUNCTION nexus.text_gated_search_allowed_1024( p_query nexus.vector(1024), p_query_text text, p_chashes bytea[], p_collections text[], p_where jsonb, p_where_path text, p_n int, p_embedding_model text, p_tenant text ) RETURNS TABLE(id text, content text, collection text, distance float8, metadata jsonb, retention text) LANGUAGE sql STABLE SECURITY INVOKER AS $$ SELECT encode(c.chash, 'hex'), c.chunk_text, c.collection, (c.embedding_1024 OPERATOR(nexus.<=>) p_query)::float8, c.metadata, c.retention FROM nexus.chunks c WHERE c.embedding_model = p_embedding_model AND c.tenant_id = p_tenant AND c.collection = ANY(p_collections) AND c.embedding_1024 IS NOT NULL AND c.chash = ANY(p_chashes) AND EXISTS (SELECT 1 FROM nexus.chunk_live_owners(c.tenant_id, c.collection, c.chash)) AND (p_where IS NULL OR c.metadata @> p_where) AND (p_where_path IS NULL OR c.metadata @@ p_where_path::jsonpath) AND (c.chunk_tsv @@ plainto_tsquery('english', p_query_text) OR p_query_text OPERATOR(nexus.<%) c.chunk_text) ORDER BY c.embedding_1024 OPERATOR(nexus.<=>) p_query, encode(c.chash, 'hex') LIMIT p_n $$;
GRANT EXECUTE ON FUNCTION nexus.text_gated_search_allowed_384(nexus.vector, text, bytea[], text[], jsonb, text, int, text, text) TO nexus_svc; GRANT EXECUTE ON FUNCTION nexus.text_gated_search_allowed_768(nexus.vector, text, bytea[], text[], jsonb, text, int, text, text) TO nexus_svc; GRANT EXECUTE ON FUNCTION nexus.text_gated_search_allowed_1024(nexus.vector, text, bytea[], text[], jsonb, text, int, text, text) TO nexus_svc;
DO $post$ DECLARE n int; BEGIN SELECT count(*) INTO n FROM pg_catalog.pg_proc p WHERE p.pronamespace = 'nexus'::pg_catalog.regnamespace AND p.proname IN ('text_gated_search_allowed_384', 'text_gated_search_allowed_768', 'text_gated_search_allowed_1024'); IF n <> 3 THEN RAISE EXCEPTION 'vectors-042-1: expected exactly 3 text_gated_search_allowed functions (one signature each), found %', n; END IF; END $post$;

rollback.sql:
DROP FUNCTION IF EXISTS nexus.text_gated_search_allowed_384(nexus.vector, text, bytea[], text[], jsonb, text, int, text, text);
DROP FUNCTION IF EXISTS nexus.text_gated_search_allowed_768(nexus.vector, text, bytea[], text[], jsonb, text, int, text, text);
